const text = $json.output[0].content[0].text;
const review = JSON.parse(text);

if (
  typeof review.approved !== 'boolean' ||
  !Array.isArray(review.issues)
) {
  throw new Error('Invalid email review response');
}

return {
  json: {
    ...$json,
    review,
    email_text: $('Create Email').item.json.output[0].content[0].text,
  },
};

const current = $input.first().json;
const filenames = current.intake.document_filenames;
if (!Array.isArray(filenames) || !filenames.length) {
  throw new Error('No source documents listed for this intake');
}
const context = {
  contact_id: current.contact_id,
  client: { first_name: current.client.first_name, last_name: current.client.last_name },
  intake: current.intake,
  clerk_assignment: current.clerk_assignment,
  paralegal_assignment: current.paralegal_assignment,
  missing_documents: current.missing_documents,
};
return filenames.map(filename => {
  if (!filename.startsWith(current.intake.intake_id + '-') ||
      !/^[A-Za-z0-9_-]+\.pdf$/i.test(filename)) {
    throw new Error('Invalid source document filename');
  }
  return { json: { source_filename: filename, case_context: context }, pairedItem: { item: 0 } };
});

const inputs = $input.all();
const context = $('Prepare Brief Document Inputs').itemMatching(0).json.case_context;
const documents = inputs.map((item, index) => {
  const source = $('Prepare Brief Document Inputs').itemMatching(index).json;
  if (typeof item.json.text !== 'string' || !item.json.text.trim()) {
    throw new Error('No extractable text in ' + source.source_filename);
  }
  return { filename: source.source_filename, text: item.json.text };
});
const expected = context.intake.document_filenames;
if (documents.length !== expected.length || expected.some(f => !documents.some(d => d.filename === f))) {
  throw new Error('Source document coverage does not match intake checklist');
}
return [{ json: { case_context: context, source_documents: documents },
  pairedItem: inputs.map((_, item) => ({ item })) }];

const content = ($json.output ?? []).flatMap(m => m.content ?? [])
  .filter(c => c.type === 'output_text').map(c => c.text).join('\n');
if (!content.trim()) throw new Error('OpenAI returned no brief text');
const clean = content.trim().replace(/^```(?:json)?\s*/i, '').replace(/\s*```$/, '');
const brief = JSON.parse(clean);
const evidence = $('Assemble Brief Evidence').item.json;
const original = $('Brief already created?').item.json;
const requiredText = ['client_name','contact_id','intake_id','prepared_by','assigned_paralegal','reason_for_intake','handoff_status'];
const issues = [];
for (const key of requiredText) {
  if (typeof brief[key] !== 'string' || !brief[key].trim()) issues.push('Missing or invalid ' + key);
}
for (const key of ['received_documents','hearing_details','missing_documents','follow_up']) {
  if (!Array.isArray(brief[key])) throw new Error('Invalid brief section: ' + key);
}
const same = (a,b) => JSON.stringify([...a].sort()) === JSON.stringify([...b].sort());
if (brief.client_name !== original.client.first_name + ' ' + original.client.last_name) issues.push('Client name mismatch');
if (brief.intake_id !== original.intake.intake_id || brief.contact_id !== original.contact_id) issues.push('Intake/contact identity mismatch');
if (brief.prepared_by !== original.clerk_assignment.staff_name) issues.push('Preparing clerk mismatch');
if (brief.assigned_paralegal !== original.paralegal_assignment.staff_name) issues.push('Assigned paralegal mismatch');
if (!same(brief.missing_documents, original.missing_documents)) issues.push('Missing-document checklist mismatch');
if (!same(brief.received_documents.map(d => d.filename), original.intake.document_filenames)) issues.push('Received-document coverage mismatch');
if (brief.received_documents.some(d => typeof d.summary !== 'string' || !d.summary.trim())) issues.push('Missing document summary');
if (brief.hearing_details.some(d => !original.intake.document_filenames.includes(d.source_filename) || typeof d.details !== 'string')) issues.push('Invalid hearing source or details');
const serialized = JSON.stringify(brief);
if ((original.client.ssn && serialized.includes(original.client.ssn)) || /\b\d{3}-\d{2}-\d{4}\b/.test(serialized)) issues.push('Prohibited identifier present');
return { json: { ...evidence, brief, deterministic_issues: issues } };

const content = ($json.output ?? []).flatMap(m => m.content ?? [])
  .filter(c => c.type === 'output_text').map(c => c.text).join('\n');
const review = JSON.parse(content.trim().replace(/^```(?:json)?\s*/i,'').replace(/\s*```$/,''));
if (typeof review.approved !== 'boolean' || !Array.isArray(review.issues) || review.issues.some(i => typeof i !== 'string')) {
  throw new Error('Invalid brief review response');
}
const draft = $('Parse Draft Brief').item.json;
const issues = [...new Set([...draft.deterministic_issues, ...review.issues])];
return { json: { ...draft, brief_review: { approved: review.approved && issues.length === 0, issues } } };

if ($json.brief_review?.approved !== true) throw new Error('Brief is not approved');
const b = $json.brief;
// Minimal local PDF renderer: no extra service, module installation or filesystem access.
const ascii = s => String(s).normalize('NFKD').replace(/[\u0300-\u036f]/g,'')
  .replace(/[\u2018\u2019]/g,"'").replace(/[\u201c\u201d]/g,'"')
  .replace(/[\u2013\u2014]/g,'-').replace(/[^\x20-\x7e\n]/g,' ');
const escapePDF = s => ascii(s).replace(/\\/g,'\\\\').replace(/\(/g,'\\(').replace(/\)/g,'\\)');
const rows=[];
function para(text) {
  const paragraphStart = rows.length;
  for (const paragraph of ascii(text).split(/\n/)) {
    let line='';
    for (let word of paragraph.split(/\s+/).filter(Boolean)) {
      if (line && line.length + word.length + 1 > 84) { rows.push({text:line}); line=''; }
      while (word.length > 84) { if(line){rows.push({text:line});line='';} rows.push({text:word.slice(0,84)});word=word.slice(84); }
      line += (line ? ' ' : '') + word;
    }
    if(line) rows.push({text:line});
  }
  rows.push({text:'',gap:5});
  if (rows.length > paragraphStart) rows[paragraphStart].blockHeight = (rows.length - paragraphStart - 1) * 14 + 5;
}
function heading(text) { rows.push({text,heading:true}); }
para(b.client_name + ' | Contact ' + b.contact_id + ' | Intake ' + b.intake_id);
para('Prepared by ' + b.prepared_by + ', law clerk');
heading('Reason for intake');para(b.reason_for_intake);
heading('Received documents');for(const d of b.received_documents){para(d.filename + '\n' + d.summary);}
heading('Hearing details as printed on the notice');
if(!b.hearing_details.length) para('No verified hearing details supplied.');
for(const h of b.hearing_details){para('Source: ' + h.source_filename + '\n' + h.details);}
heading('Missing documents');
if(!b.missing_documents.length)para('None under the current intake checklist.');
for(const d of b.missing_documents)para('- ' + d.replace(/-/g,' '));
heading('Follow-up');for(const f of b.follow_up)para('- ' + f);
heading('Handoff status');para(b.handoff_status);
const streams=[];let commands=[],y=0;
const draw=(text,font,size,x,baseline)=>commands.push('BT /'+font+' '+size+' Tf '+x+' '+baseline+' Td ('+escapePDF(text)+') Tj ET');
function startPage(){commands=['0.13 0.22 0.29 rg'];draw('FICTIONAL DEMO DOCUMENT | INTERNAL INTAKE','F2',8,52,746);draw('Intake Brief','F2',24,52,708);y=676;}
function finishPage(){draw('Fictional case information for the law firm intake demo.','F1',8,52,40);draw(String(streams.length+1),'F1',8,554,40);streams.push(commands.join('\n'));}
startPage();
for(let i=0;i<rows.length;i++){
 const r=rows[i],height=r.heading?25:(r.gap||14);
 if ((r.blockHeight && r.blockHeight < 300 && y - r.blockHeight < 70) || y-height < (r.heading?120:70)){finishPage();startPage();}
 if(r.heading){y-=8;draw(r.text,'F2',12,52,y);y-=17;}
 else {if(r.text)draw(r.text,'F1',10,52,y);y-=height;}
}
finishPage();
const objects=[null,'<< /Type /Catalog /Pages 2 0 R >>','',
 '<< /Type /Font /Subtype /Type1 /BaseFont /Courier /Encoding /WinAnsiEncoding >>',
 '<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica-Bold /Encoding /WinAnsiEncoding >>'];
const pageIDs=[];
for(const stream of streams){const pageID=objects.length;const contentID=pageID+1;pageIDs.push(pageID);
 objects.push('<< /Type /Page /Parent 2 0 R /MediaBox [0 0 612 792] /Resources << /Font << /F1 3 0 R /F2 4 0 R >> >> /Contents '+contentID+' 0 R >>');
 objects.push('<< /Length '+Buffer.byteLength(stream,'ascii')+' >>\nstream\n'+stream+'\nendstream');}
objects[2]='<< /Type /Pages /Kids ['+pageIDs.map(id=>id+' 0 R').join(' ')+'] /Count '+pageIDs.length+' >>';
let pdf='%PDF-1.4\n';const offsets=[0];
for(let i=1;i<objects.length;i++){offsets.push(Buffer.byteLength(pdf,'ascii'));pdf+=i+' 0 obj\n'+objects[i]+'\nendobj\n';}
const xref=Buffer.byteLength(pdf,'ascii');pdf+='xref\n0 '+objects.length+'\n0000000000 65535 f \n';
for(let i=1;i<offsets.length;i++)pdf+=String(offsets[i]).padStart(10,'0')+' 00000 n \n';
pdf+='trailer\n<< /Size '+objects.length+' /Root 1 0 R >>\nstartxref\n'+xref+'\n%%EOF\n';
const fileName=b.intake_id+'-intake-brief.pdf';
const data=await this.helpers.prepareBinaryData(Buffer.from(pdf,'ascii'),fileName,'application/pdf');
return {json:{...$json,brief_file_name:fileName,brief_path:'/files/output/resource/'+fileName},binary:{data}};

const original = $('Brief already created?').item.json;
const generated = $('Render Approved Brief PDF').item.json;
return { json: { ...original, brief_path: generated.brief_path,
  brief_review: generated.brief_review, brief_created_this_run: true } };

const original = $('Brief already created?').item.json;
return { json: { ...original, brief_review: $json.brief_review,
  brief_created_this_run: false, brief_path_status: 'review_rejected',
  handoff_skipped: true } };
